import pandas as pd

def clean(df):
    # Fix text numbers in body_mass_g: remove commas
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False).astype(float)

    # Fix case variants in island
    island_mapping = {'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'}
    df['island'] = df['island'].map(island_mapping).fillna(df['island'])

    # Fix case variants in sex
    sex_mapping = {'MALE': 'male', 'FEMALE': 'female'}
    df['sex'] = df['sex'].map(sex_mapping).fillna(df['sex'])

    return df

def answer(df):
    # Calculate average body mass for each species
    result = df.groupby('species', as_index=False)['body_mass_g'].mean()
    # Convert to dict with species as key and average body mass as value
    return dict(zip(result['species'], result['body_mass_g'].round(2)))
